selector_to_html = {"a[href=\"syllabus.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Syllabus<a class=\"headerlink\" href=\"#syllabus\" title=\"Link to this heading\">#</a></h1><h2>Course overview<a class=\"headerlink\" href=\"#course-overview\" title=\"Link to this heading\">#</a></h2><p>See the <a class=\"reference external\" href=\"https://catalog.uark.edu/search/?P=MATH%2031003\">University of\nArkansas mathematics course listing</a>. Prerequisites are MATH 26103 or MATH\n28003; the pre- or corequisite is MATH 30803 or MATH 30903. You should be\ncomfortable working with sets, functions, relations, basic proofs and\nmathematical arguments, algebraic manipulation, and polynomials.</p><p>Combinatorics begins with a simple question: How many ways can we arrange a\ncollection of objects? Can a schedule, pairing, or design be made at all? What\nchanges when two arrangements should count as the same? These questions show up\nin mathematics, computer science, probability, and more.</p>", "a[href=\"#combinatorics\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Combinatorics<a class=\"headerlink\" href=\"#combinatorics\" title=\"Link to this heading\">#</a></h1><p><strong>Course:</strong> <span>MATH 31003-01</span><span class=\"semantic-line-break\"></span><strong>Semester:</strong> <span>Fall 2026</span><span class=\"semantic-line-break\"></span><strong>Instructor:</strong> <span>Gennady Uraltsev</span><span class=\"semantic-line-break\"></span><strong>Meetings:</strong> <span>Monday, Wednesday, Friday 8:35-9:25 a.m.</span>, <span>GEAR 108</span></p><p>Welcome to Combinatorics! We will explore the mathematics of discrete objects:\nthe many ways things can be selected, arranged, connected, and counted. The\ncourse covers basic combinatorial techniques, the principle of\ninclusion-exclusion, generating functions, and recursive relations. Additional\ntopics may include modular arithmetic and applications to encryption, coding\ntheory, graph theory, counting with symmetries, and algebraic structures.</p>", "a[href=\"#start-here\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Start here<a class=\"headerlink\" href=\"#start-here\" title=\"Link to this heading\">#</a></h2><p>Please check the <a class=\"reference internal\" href=\"calendar.html\"><span class=\"doc\">course calendar</span></a> for holidays, University\ndeadlines, and topic updates. Course announcements, grades, and submission\nlinks are maintained in <a class=\"reference external\" href=\"https://learn.uark.edu/ultra/courses/_529368_1/\"><span>Blackboard</span></a>.</p>", "a[href=\"calendar.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Calendar<a class=\"headerlink\" href=\"#calendar\" title=\"Link to this heading\">#</a></h1><p>I will put all deadlines on the <a class=\"reference external\" href=\"https://learn.uark.edu/ultra/courses/_529368_1/calendar/\">Blackboard\nCalendar</a>. Please check it regularly.</p>", "a[href=\"lecture-notes/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Lecture Notes<a class=\"headerlink\" href=\"#lecture-notes\" title=\"Link to this heading\">#</a></h1><p>These notes are the main guide through the course. They are organized by unit\nand mathematical topic rather than by the particular class meeting in which a\ntopic appeared. Draft and future units remain in the instructor\u2019s private\ncourse design collection until they are ready for publication.</p>", "a[href=\"assignments/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Assignments<a class=\"headerlink\" href=\"#assignments\" title=\"Link to this heading\">#</a></h1><h2>Written homework<a class=\"headerlink\" href=\"#written-homework\" title=\"Link to this heading\">#</a></h2><p>Submit your work through Gradescope using\n<a class=\"reference external\" href=\"https://learn.uark.edu/ultra/courses/_529368_1/outline/\">Blackboard\u2019s assignment area</a>. The\nprintable version is available from each assignment page.</p><p>Weekly homework gives you a chance to work through more involved problems using\nthe techniques we have learned. A complete solution includes both a clear\nexplanation and correct computations. Every exercise is required; point values\nindicate how much each exercise contributes to the assignment grade.</p>", "a[href=\"resources.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Resources<a class=\"headerlink\" href=\"#resources\" title=\"Link to this heading\">#</a></h1><p>I will provide lecture notes or detailed references for all topics we cover. I\nmay also include optional videos and other additional material as alternative\nexplanations or extra practice.</p>"}
skip_classes = ["headerlink", "sd-stretched-link", "no-hover-preview"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`article.bd-article ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
